/* ================= READING 2 · LEADERSHIP AND ENVIRONMENTAL SUSTAINABILITY (Zacher, Kühner, Katz & Rudolph, 2024) ================= */

/* ---------- step 1 · the problem: behavior, or something else? ---------- */
(function(){
const O=[['What the leader is,','knows or wants'],['What the leader','does'],['What results','from it']];
const rd=(k,bin,ic,c,say)=>({k,bin,ic,c,q:'What kind of thing is this?',o:[O[bin]].concat(O.filter((_,j)=>j!==bin)),say});
const RS=[
rd('a',1,'☕',['Dana uses reusable cups','in her team meetings.'],`<b>Behavior.</b> Something Dana does, that she controls and that can be counted. A leader using reusable cups in team meetings is the article's own example of a (low-intensity) leader green behavior.`),
rd('b',0,'📚',['Dana knows a lot about','environmental law.'],`<b>Something she knows: an antecedent.</b> Knowledge comes before behavior and may lead to it. It is not yet anything Dana does.`),
rd('c',2,'♻️',['Dana’s team recycles more','than it did last year.'],`<b>A result: a consequence.</b> This is what her followers do. It may follow from Dana's behavior, but it is not her behavior.`),
rd('d',0,'🌲',['Dana cares deeply','about nature.'],`<b>Something she is or wants: an antecedent.</b> Values and attitudes sit before behavior. A leader can care deeply and still change nothing.`),
rd('e',1,'🗣️',['Dana persuades upper management to','adopt a new sustainability policy.'],`<b>Behavior.</b> Again something she does. The article uses this example for a <b>high-intensity</b> leader green behavior: more effort, more risk, more radical than the reusable cups.`),
rd('f',2,'📈',['The company’s environmental','performance improved this year.'],`<b>A result: a consequence</b>, at the level of the organization.`)];
SEQ('ldSort','lsOut',{title:'A leader’s behavior, or something else?',hook:'Keep three things apart: before · the behavior · after',unit:'Statement',
 draw(S){const B=[[12,'#efeaf7','#6d5a9e','🧠 BEFORE','is · knows · wants',0],[222,'#e2f1e6','#2f8a57','🖐️ THE BEHAVIOR','what the leader does',1],[432,'#f6eedd','#a8854a','🎯 AFTER','what results',2]];let s='';
  B.forEach(b=>{const its=RS.filter(r=>r.bin===b[5]&&(S.got[r.k]||S.end));s+=BX(b[0],62,196,190,its.length?b[1]:'#fff',b[2],its.length?2.4:1.5)+`<text x="${b[0]+98}" y="88" ${mid} font-weight="700" font-size="12.5" fill="${b[2]}">${b[3]}</text><text x="${b[0]+98}" y="106" ${mid} class="t-s" font-size="10.5">${b[4]}</text>`+its.map((r,q)=>`<text x="${b[0]+58+q*80}" y="170" ${mid} font-size="32">${r.ic}</text>`).join('')+(b[5]<2?`<text x="${b[0]+203}" y="162" ${mid} font-size="20" fill="#c9a96e">→</text>`:'')});return s},
 rounds:shuf(RS),
 end:['Antecedents, the behavior itself, and consequences are three different things.','A "leadership style" label tends to mix all three in one word.'],
 endOut:`<b>🏁 This is the problem the article starts from.</b> Labels such as "environmentally-specific transformational leadership" describe a pattern of behavior that is <b>assumed</b> to have certain causes and certain good results. The cause, the behavior and the result are packed into one word. The authors call these "adjective leadership" styles and say they <b>conflate</b> (mix up) the behavior with its assumed antecedents or consequences.`});
})();

/* ---------- step 2 · what 210 studies looked at (Table 1) ---------- */
(function(){
const LC=[['Green transformational',62],['Servant',24],['Responsible',20],['Environmental',18],['Ethical',18],['Green supervisory support',12],['Sustainable',10]];
const AN=[['Leader characteristics',19],['Context',12],['Follower characteristics',1]];
const CO=[['Follower green behavior',143],['Follower characteristics',85],['Context',60],['Green organizational results',33],['Follower well-being, turnover',4],['Other organizational results',4]];
const RS=[
{k:'a',ic:'🔎',c:['The authors searched article titles (September 2023)','and got 1721 hits. How many papers were relevant?'],q:'Choose.',o:[['210'],['About 1000'],['Nearly all']],set:{s0:1},say:`<b>210 papers</b>, of which 203 were empirical studies, published between 2000 and 2023. The search was done in Web of Science on article titles, and relevance was judged from the abstracts. The table on the right of this step ("Table 1 in our words") gives all the counts.`},
{k:'b',ic:'🏷️',c:['Which leadership label did these','studies use most often?'],q:'Choose.',o:[['Green transformational','leadership'],['Ethical','leadership'],['Servant','leadership']],set:{s1:1},say:`<b>Environmentally-specific transformational leadership</b>: 62 of the 210 studies. Then servant leadership (24), responsible leadership (20), environmental leadership (18), ethical leadership (18), environmentally-specific supervisory support (12), sustainable leadership (10), and other constructs (47). Almost all are <b>styles</b>. Only a few studies measured what leaders themselves do for the environment, for example their conservation behavior (turning off lights) and advocacy (making suggestions to committees; Robertson &amp; Barling, 2013).`},
{k:'c',ic:'⚖️',c:['What did researchers study more: what leads to','green leadership, or what follows from it?'],q:'Choose.',o:[['What follows','from it'],['What leads','to it'],['About','the same']],set:{s2:1},say:`<b>What follows from it, by far.</b> 191 studies looked at consequences of green leadership, 28 at its antecedents. (A study can count in more than one group.)`},
{k:'d',ic:'👥',c:['Of the 28 studies on antecedents, how many looked at','followers as a cause of green leadership?'],q:'Choose.',o:[['Only 1'],['About 10'],['About 20']],set:{s3:1},say:`<b>Only one</b> (Javaid and colleagues, 2023: follower active engagement and critical thinking were positively related to leader green behavior). Leader characteristics: 19 studies, for example personal values, conscientiousness and moral reflectiveness, environmental knowledge, and more advanced "stages of consciousness" (a long-range focus and a systemic perspective; Boiral and colleagues, 2015, 2018). Contextual characteristics: 12 studies, for example organizational promotion of environmental practices and green human resource management.`},
{k:'e',ic:'🎯',c:['Which consequence of green leadership','was studied most?'],q:'Choose.',o:[['Followers’','green behavior'],['The company’s','environmental results'],['Followers’','well-being']],set:{s4:1},say:`<b>Followers' green behavior</b>: 143 studies. Then follower characteristics such as environmental commitment and passion (85), contextual characteristics such as green human resource management and organizational environmental support (60), and green organizational results such as company environmental performance (33). Follower outcomes such as well-being and turnover intentions: only 4. Other organizational results such as financial performance: only 4. Besides this, 127 studies looked at mediators (49), moderators (54) or green leadership itself as a moderator (24).`}];
SEQ('ldLit','llOut',{title:'What did 210 studies look at?',hook:'Bars are numbers of studies (k) from Table 1',unit:'Question',
 draw(S){let s='';const hd=(x,y,t)=>`<text x="${x}" y="${y}" font-weight="700" font-size="11.5" fill="#34466b">${t}</text>`;
  s+=hd(12,70,'LEADERSHIP LABELS')+LC.map((r,j)=>S.s1||S.end?BAR(12,78+j*21,r[1],[150,1.9],j?'#34466b':'#2f8a57',r[0],r[1]):`<text x="12" y="${88+j*21}" font-size="10.8" fill="#9aa3b2">${r[0]}</text><text x="162" y="${88+j*21}" font-size="10.8" fill="#c9cfd9">?</text>`).join('');
  s+=hd(330,70,'WHAT LEADS TO IT'+(S.s2||S.end?' · 28 studies':''))+AN.map((r,j)=>S.s3||S.end?BAR(330,78+j*19,r[1],[160,.8],'#6d5a9e',r[0],r[1]):`<text x="330" y="${88+j*19}" font-size="10.8" fill="#9aa3b2">${r[0]}</text><text x="490" y="${88+j*19}" font-size="10.8" fill="#c9cfd9">?</text>`).join('');
  s+=hd(330,148,'WHAT FOLLOWS'+(S.s2||S.end?' · 191 studies':''))+CO.map((r,j)=>S.s4||S.end?BAR(330,156+j*18,r[1],[160,.8],'#a8854a',r[0],r[1]):`<text x="330" y="${166+j*18}" font-size="10.8" fill="#9aa3b2">${r[0]}</text><text x="490" y="${166+j*18}" font-size="10.8" fill="#c9cfd9">?</text>`).join('');
  s+=`<text x="12" y="252" class="t-s" font-size="10.5">${S.s0||S.end?'1721 hits → 210 relevant papers (203 empirical), 2000 to 2023':'1721 hits → ? relevant papers'}</text>`;return s},
 rounds:RS,
 end:['Much research on styles and on followers’ green behavior.','Little on the leader’s own behavior, its causes, and its other results.'],
 endOut:`<b>🏁 A lopsided literature.</b> Researchers mostly asked: does a green leadership <b>style</b> go with <b>followers' green behavior</b>? A meta-analysis says yes, moderately (Katz and colleagues, 2022). But every study combined its own set of leadership constructs, mediators, moderators and levels, so the knowledge is <b>fragmented</b>. That is the second problem the article wants to solve, with one integrating model.`,
 extras:[['🧪 Example findings the review mentions',`<b>Supervisory support.</b> An early study described six dimensions of environmentally-specific supervisory support: encouragement of innovation, competence building, communication, information dissemination, rewards and recognition, and management of goals and responsibilities (Ramus &amp; Steger, 2000). Employee perceptions of such support relate positively to their environmental commitment and behavior. <b>Mediators and moderators.</b> In a multi-wave study, supervisory support lowered counterproductive sustainability behaviors through employee environmental commitment (Paillé and colleagues, 2019). Environmentally-specific transformational leadership predicted green behavior through the perceived pro-environmental climate, but only among employees with a high environmental locus of control (Robertson &amp; Carleton, 2018). <b>Leadership as moderator.</b> High environmental leadership strengthened the positive relation between environmental management practices and a company's green innovation performance (Zhang &amp; Ma, 2021). <b>Organization level.</b> Leaders' citizenship behavior for the environment (Boiral and colleagues, 2015) and environmentally-specific transformational leadership (Riva and colleagues, 2021) were positively related to company environmental performance.`]]});
})();

/* ---------- step 3 · key concepts: four routes from a leader to the environment ---------- */
(function(){
const L=[['d','🖐️','Directly','the leader acts herself','#2f8a57','#e2f1e6'],['c','🧰','Through the work context','new policies, new tasks','#4f6aa0','#e3ecf7'],['f','👥','Through followers','orders, inspiration, example','#6d5a9e','#efeaf7'],['o','🏢','Through the organization','its decisions as a whole','#34466b','#e3ecf7']];
const RS=[
{k:'a',pick:'d',ic:'♻️',c:['Elena sorts her own waste','and recycles at the office.'],say:`<b>🖐️ Directly.</b> The leader herself benefits the environment. Recycling is the article's example of a direct behavior.`},
{k:'b',pick:'d',ic:'✈️',c:['Elena flies to meetings that could','easily have been video calls.'],say:`<b>🖐️ Directly, and harmful.</b> The definition says leader green behavior contributes to <b>or detracts from</b> sustainability. Unnecessary business travel is one of the article's examples of a counterproductive sustainability behavior, next to wasting resources and improper waste disposal.`},
{k:'c',pick:'c',ic:'📋',c:['Elena writes a new team policy and adds','a green task to two job descriptions.'],say:`<b>🧰 Through the work context.</b> Indirect: she changes contextual work and organizational characteristics, for example by creating new policies or work tasks. The environment benefits through what that changed context does.`},
{k:'d',pick:'f',ic:'📣',c:['Elena instructs, inspires and shows','her team how to save energy.'],say:`<b>👥 Through followers.</b> Indirect: she changes follower behavior. The article names three ways: orders, inspirational motivation and behavioral modeling (being the example).`},
{k:'e',pick:'o',ic:'💶',c:['In the investment committee, Elena argues','for the cleaner production line.'],say:`<b>🏢 Through the organization.</b> Indirect: she changes organizational behavior, for example through her influence in environmental investment decisions.`},
{k:'f',pick:'f',ic:'🙋',c:['Tariq has no formal leadership role. He starts','a green project and colleagues follow him.'],say:`<b>👥 Through followers</b>, and note who leads. Leader green behaviors may also be shown by people <b>without</b> an official supervisory role who lead sustainability initiatives inside or outside a team: "shared leadership" or "emergent leadership" (Gallagher and colleagues, 2020).`}];
SEQ('ldRoute','lrOut',{title:'Four routes from a leader to the environment',hook:'One direct route, three indirect ones',unit:'Action',cue:'Tap the route this action takes',
 draw(S){let s=BX(12,112,96,96,'#f6eedd','#a8854a',2,18)+`<text x="60" y="156" ${mid} font-size="30">🧑‍💼</text><text x="60" y="184" ${mid} font-weight="700" font-size="12" fill="#a8854a">Leader</text>`+BX(548,112,80,96,'#e2f1e6','#2f8a57',2,18)+`<text x="588" y="160" ${mid} font-size="30">🌍</text><text x="588" y="188" ${mid} class="t-s" font-size="10.5">helps or harms</text>`;
  L.forEach((l,j)=>{const y=60+j*50,its=RS.filter(r=>r.pick===l[0]&&(S.got[r.k]||S.end));s+=`<g ${S.z(l[0])}>${BX(122,y,412,42,its.length?l[5]:'#fff',its.length?l[4]:'#c9cfd9',its.length?2.3:1.5,12)}<text x="146" y="${y+28}" ${mid} font-size="19">${l[1]}</text><text x="168" y="${y+18}" font-weight="700" font-size="12.3" fill="${l[4]}">${l[2]}</text><text x="168" y="${y+33}" class="t-s" font-size="10.5">${l[3]}</text>${its.map((r,q)=>`<text x="${470+q*34}" y="${y+29}" ${mid} font-size="20">${r.ic}</text>`).join('')}</g>`});return s},
 rounds:shuf(RS),
 end:['A leader can affect the environment directly, or indirectly through the','work context, through followers, or through the organization’s decisions.'],
 endOut:`<b>🏁 This is the article's definition, drawn.</b> <b>Leader green behavior</b> is a meaningful set of a leader's goal-directed, scalable actions that are linked with and contribute to, or detract from, environmental sustainability. The actions are under the leader's control and work directly or through the three indirect routes. That is wider than a leadership style, which only covers how leaders influence followers.`,
 extras:[['🖐️ The green six, now for leaders',`The authors divide leader green behavior with the same taxonomy as reading 1: <b>transforming</b> (for example using responsible alternative materials and means), <b>conserving</b> (reducing use, reusing, recycling), <b>avoiding harm</b> (preventing pollution, monitoring impact), <b>influencing others</b> (educating and training; managing, facilitating, coordinating; leading, encouraging, supporting), <b>taking initiative</b> (initiating programs, lobbying, activism) and <b>counterproductive sustainability behaviors</b> (wasting resources, improper waste disposal, unnecessary business travel). Like employee green behavior, it is a compound performance domain: it cuts across task-focused, follower-focused, change-focused and counterproductive leader behavior, with a shared focus on sustainability.`],['📏 The three lines, now for leaders',`<b>In-role</b> (part of the leader's prescribed duties) or <b>extra-role</b> (discretionary, as an organizational citizen). <b>Direct</b> or <b>indirect</b>. <b>Low intensity</b> (less effort and risk, more incremental: reusable cups in meetings) or <b>high intensity</b> (more effort and risk, more radical: persuading upper management to adopt a new policy).`]]});
})();

/* ---------- shared: the model as a 3 × 3 grid (Figure 1) ---------- */
const LDMODEL=(S,pins)=>{const rows=[['ORGANIZATION',58,'#34466b','#e3ecf7'],['LEADER',126,'#a8854a','#f6eedd'],['FOLLOWERS',194,'#6d5a9e','#efeaf7']];
 const cell=(x,y,w,a,b,c,f,strong)=>BX(x,y,w,56,f,c,strong?2.6:1.4,12)+`<text x="${x+w/2}" y="${y+24}" ${mid} font-weight="700" font-size="${strong?12.5:11.5}" fill="${c}">${a}</text><text x="${x+w/2}" y="${y+41}" ${mid} class="t-s" font-size="10.5">${b}</text>`;
 let s='';rows.forEach(r=>{s+=`<text x="12" y="${r[1]+3}" font-size="9.5" font-weight="700" fill="${r[2]}" opacity=".0">${r[0]}</text>`});
 s+=cell(12,60,196,'🏢 Context','strategy · climate · tools · design','#34466b','#e3ecf7')+cell(432,60,196,'🏢 Organization results','performance · attractiveness','#34466b','#e3ecf7');
 s+=cell(12,128,196,'🧠 Leader antecedents','indirect → know, can, want','#a8854a','#f6eedd')+cell(222,128,196,'🧑‍💼 LEADER GREEN BEHAVIOR','the green six','#2f8a57','#e2f1e6',1)+cell(432,128,196,'🧑‍💼 Leader results','needs · performance · success','#a8854a','#f6eedd');
 s+=cell(12,196,196,'🧠 Follower antecedents','indirect → know, can, want','#6d5a9e','#efeaf7')+cell(222,196,196,'👥 Follower green behavior','the green six','#6d5a9e','#efeaf7')+cell(432,196,196,'👥 Follower results','needs · performance','#6d5a9e','#efeaf7');
 s+=`<text x="320" y="92" ${mid} class="t-s" font-size="10.5">three levels · left to right:</text><text x="320" y="106" ${mid} class="t-s" font-size="10.5">before → behavior → after</text>`;
 const P={1:[215,156],2:[320,190],3:[110,122],4:[290,190],5:[215,112],6:[425,156],7:[425,196],8:[425,112]};
 Object.keys(P).forEach(n=>{const on=pins[n];s+=`<circle cx="${P[n][0]}" cy="${P[n][1]}" r="11" fill="${on?'#c9a96e':'#fff'}" stroke="${on?'#a8854a':'#c9cfd9'}" stroke-width="2"/><text x="${P[n][0]}" y="${P[n][1]+4}" ${mid} font-size="11.5" font-weight="700" fill="${on?'#fff':'#9aa3b2'}">${n}</text>`});return s};

/* ---------- step 4 · into the leader: propositions 1, 2, 3 ---------- */
(function(){
const RS=[
{k:'a',p:1,ic:'🌳',c:['Ravi, a team leader, has always valued nature.','How does that value turn into green behavior?'],q:'Choose the path the model proposes.',o:[['Through what he knows,','can do and wants'],['Directly: a value','is enough']],say:`<b>Proposition 1.</b> Leaders' abilities, values, personality, attitudes, beliefs and affect are <b>indirect</b> determinants. They are proposed to influence leader green behavior <b>via</b> the three <b>direct</b> determinants: declarative knowledge, procedural knowledge or skills, and motivation. Evidence so far: leader environmental knowledge and motivation predict leader green behavior, and attitudes, norms, control, self-efficacy, conscientiousness and moral reflectiveness are related to it. But the chain itself (indirect → direct → behavior) has not been tested yet.`},
{k:'b',p:2,ic:'📝',c:['Ravi’s team petitions him for hybrid working,','to cut the emissions of commuting.'],q:'How do the followers change their leader here?',o:[['They change what he','knows and wants'],['He copies','what they do']],say:`<b>Proposition 2a: bottom-up, through "influencing others".</b> Followers can educate, persuade or encourage their leader. That works <b>indirectly</b>, through the leader's antecedents: his knowledge, skills and motivation, or his attitudes, beliefs and affect. Petitioning for hybrid work is the article's example.`},
{k:'c',p:2,ic:'☕',c:['Ravi sees his whole team bring reusable cups.','The next week he brings one too.'],q:'How do the followers change their leader here?',o:[['He copies them:','behavioral modeling'],['They change what he','knows with arguments']],say:`<b>Proposition 2b: bottom-up, through modeling.</b> Followers show green (or counterproductive) behaviors, and the leader observes and models them: a <b>direct</b> path. Evidence for proposition 2: only one study is somewhat consistent with it (Javaid and colleagues, 2023), and it did not test the mechanisms.`},
{k:'d',p:3,ic:'🚗',c:['The company replaces all petrol pool cars','with electric ones.'],q:'How does the context change Ravi’s behavior?',o:[['Directly: it makes the','behavior possible'],['Only by first changing','his attitude']],say:`<b>Proposition 3b: the context acts directly.</b> Strategy, initiatives, culture, climate, equipment, materials, technology and work design can physically and socially facilitate or constrain leader green behavior. The context can also work <b>indirectly</b>, through the leader's antecedents (<b>3a</b>): one study found that organizational promotion of environmental practices and stakeholder demands were related to supervisors' commitment to the environment (Cantor and colleagues, 2015). Another found that green human resource management was related to leader green behavior via green work climate (Rubel and colleagues, 2021).`},
{k:'e',p:3,ic:'📕',c:['The company has a clear sustainability policy that','leaves little choice. Ravi’s own green motivation…'],q:'…now matters:',o:[['less: the situation','steers everyone'],['more: rules wake','motivation up']],say:`<b>Proposition 3c, part one: situation strength.</b> A "strong situation" limits people's discretion (free choice), so individual differences have less room to show. With a clear policy, leader green behavior should depend less on the leader's own environmental motivation. In "weak situations", which leave discretion, individual differences should matter more (situation strength theory; Meyer and colleagues, 2010).`},
{k:'f',p:3,ic:'🚲',c:['The office is designed green: it invites green','behavior at every turn. Ravi’s green motivation…'],q:'…now turns into behavior:',o:[['more easily: the context','activates it'],['less easily: nothing','is left to do']],say:`<b>Proposition 3c, part two: trait activation.</b> A context that emphasizes sustainability (environmental initiatives, green work design) should <b>strengthen</b> the link between a leader's relevant individual differences and behavior: a green office design should help pro-environmental motivation turn into behavior (trait activation theory; Tett and colleagues, 2013). Evidence: one cross-sectional study, in which perceived behavioral control was more strongly related to managers' citizenship behavior for the environment when subjective social norms were high (Akterujjaman and colleagues, 2022).`}];
SEQ('ldIn','liOut',{title:'What leads to leader green behavior?',hook:'Propositions 1, 2 and 3: the arrows into the middle box',unit:'Case',
 draw(S){const pins={};RS.forEach(r=>{if(S.got[r.k]||S.end)pins[r.p]=1});return LDMODEL(S,pins)},
 rounds:RS,
 end:['Into the leader: his own antecedents (1), his followers from below (2),','and the context from above (3), which can also strengthen or weaken (1).'],
 endOut:`<b>🏁 Three ways in.</b> <b>1</b> from the leader: indirect determinants through knowledge, skills, motivation. <b>2</b> from followers: (a) through the leader's antecedents, (b) through modeling. <b>3</b> from the context: (a) through the leader's antecedents, (b) directly, (c) by changing how strongly the leader's antecedents show in behavior. The two theories behind 3c do not contradict each other: a strong situation takes the choice away; a trait-activating context invites the behavior but leaves the choice.`});
})();

/* ---------- step 5 · out of the leader: propositions 4 and 5 ---------- */
(function(){
const T={pf:['🎓',['works on','the person'],'Person-focused action','proposition 4a','#6d5a9e','#efeaf7'],bm:['👣',['shows it','herself'],'Behavioral modeling','proposition 4b','#2f8a57','#e2f1e6'],sf:['⚙️',['changes','the system'],'System-focused action','proposition 5a','#34466b','#e3ecf7'],ma:['🎚️',['turns the system','up or down'],'Moderating action','proposition 5b','#a8854a','#f6eedd']};
const KS=Object.keys(T);
const RS=[
{k:'a',pick:'pf',ic:'🧑‍🏫',c:['Maya trains her team in sorting waste','and explains why it matters.'],say:`<b>🎓 Person-focused action (4a).</b> Through the "influencing others" dimension (training, instructing, persuading, encouraging) a leader may raise follower green behavior <b>indirectly</b>, via followers' knowledge, skills and motivation or via their indirect antecedents such as attitudes. Example study: environmentally-specific transformational leadership and leader green behavior were positively related to employees' environmental passion, which was related to their green behavior (Robertson &amp; Barling, 2013).`},
{k:'b',pick:'bm',ic:'🚲',c:['Maya cycles to work every day. After a','while, half of her team does too.'],say:`<b>👣 Behavioral modeling (4b).</b> Followers observe the leader's own green (or counterproductive) behaviors and copy them: a <b>direct</b> path. A recent cross-sectional study built on social learning theory found that the leader's green role model influence and followers' green self-efficacy mediated, one after the other, the link between leader and follower green behavior (Shao and colleagues, 2023). This is the "trickle-down" effect.`},
{k:'c',pick:'sf',ic:'📊',c:['Maya adds a sustainability goal to','everyone’s yearly performance review.'],say:`<b>⚙️ System-focused action (5a).</b> Through "transforming", "avoiding harm" and "taking initiative", leaders can change contextual antecedents such as policies, practices and work design. The changed context then influences followers' antecedents, their behavior, or the link between the two. Putting sustainability into performance management is the article's example. Studies found effects of green leadership on green human resource management, environmental management practices, and organizational environmental support.`},
{k:'d',pick:'ma',ic:'📨',c:['Head office sends a new green policy. Maya decides','whether and how her team will apply it.'],say:`<b>🎚️ Moderating action (5b).</b> The leader strengthens or weakens the impact the context has on followers. Deciding whether and how to implement a new policy is the article's example. Study: the positive links of green human resource management with green passion and with employee green advocacy were stronger when supervisory support for the environment was high (Liu and colleagues, 2023).`},
{k:'e',pick:'pf',ic:'💬',c:['Maya keeps encouraging green ideas.','Her team’s passion for the topic grows.'],say:`<b>🎓 Person-focused action (4a)</b> again: she works on a follower antecedent (here passion, part of motivation), and that antecedent is expected to raise behavior.`},
{k:'f',ic:'🎁',c:['Some of Maya’s people act green only for rewards','or pressure (external motivation).'],q:'Does that motivation go with green behavior?',o:[['Yes, when her green','leadership is high'],['Yes, always'],['No, never']],set:{c4:1},say:`<b>Proposition 4c: the leader changes the strength of a follower path.</b> The leader's behavior itself creates a weak or strong situation, or a more or less trait-activating context, for followers. Study: the link between employees' external motivation and their green behavior was <b>positive</b> when environmental transformational leadership was high and <b>negative</b> when it was low (Graves and colleagues, 2013).`}];
SEQ('ldOut','loOut',{title:'How does a leader’s green behavior reach followers?',hook:'Hook: teach them · show them · change the system · steer the system',unit:'Case',
 draw(S){let s='';KS.forEach((k,j)=>{const [ic,pl,nm,con,c,f]=T[k],x=12+(j%2)*312,y=58+Math.floor(j/2)*98,on=S.end||RS.some(r=>r.pick===k&&S.got[r.k]);
   s+=`<g ${S.z(k)}>${BX(x,y,304,90,on?f:'#fff',on?c:'#c9cfd9',on?2.4:1.5)}<text x="${x+36}" y="${y+54}" ${mid} font-size="28">${ic}</text>`+TL(x+72,y+(on?26:40),pl,`font-weight="700" font-size="12.5" fill="#34466b"`,16)+(on?`<text x="${x+72}" y="${y+64}" font-weight="700" font-size="12" fill="${c}">${nm}</text><text x="${x+72}" y="${y+80}" class="t-s" font-size="10.5">${con}</text>`:'')+'</g>'});
  if(S.c4||S.end)s+=`<circle cx="320" cy="152" r="26" fill="#fff" stroke="#c9a96e" stroke-width="2.5"/><text x="320" y="149" ${mid} font-size="10.5" font-weight="700" fill="#a8854a">4c</text><text x="320" y="163" ${mid} font-size="9.5" fill="#a8854a">strength</text>`;return s},
 rounds:RS,
 end:['Two paths straight to followers (4a, 4b), two through the context (5a, 5b),','and the leader can change how strongly follower antecedents work (4c).'],
 endOut:`<b>🏁 Five ways out.</b> The four names come from a model about leadership and employee health (Wegge and colleagues, 2014) that the authors borrow: <b>person-focused action</b>, <b>behavioral modeling</b>, <b>system-focused action</b> and <b>moderating action</b>. Notice which green behaviors carry which path: "influencing others" for 4a; the leader's own behaviors for 4b; "transforming", "avoiding harm" and "taking initiative" for 5a.`});
})();

/* ---------- step 6 · consequences and how much evidence there is ---------- */
(function(){
const O=[['None','yet'],['One or','very few studies'],['Several','studies']];
const ROWS=[['1','Leader’s traits work through know, can, want',0],['2','Followers influence the leader',1],['3','Context influences the leader',2],['4','Leader → followers’ green behavior',2],['5','Leader → context → followers',2],['6','Results for the leader',0],['7','Results for followers (well-being)',1],['8','Results for the organization',2]];
const rd=(k,row,ic,c,say)=>({k,row,ic,c,q:'How much research exists on this?',o:[O[ROWS[row][2]]].concat(O.filter((_,j)=>j!==ROWS[row][2])),set:{['r'+row]:1},say});
const RS=[
rd('a',5,'🧑‍💼',['PROPOSITION 6 · Green behavior is good for the leader:','need satisfaction, performance, leadership success.'],`<b>None yet.</b> No research has examined effects of leader green behavior on outcomes for the leader. The proposition has a condition: it depends on the behavior being <b>congruent</b> (in line) with leader and contextual antecedents. Leaders with stronger environmental values are more likely to feel need satisfaction, and then well-being, when they act green. And when the organization values sustainability, green behavior should lead to more favorable evaluations of leadership success. It should also show in the leader's own environmental performance, such as lower personal resource use and waste.`),
rd('b',6,'🙂',['PROPOSITION 7 · A leader’s green behavior is good for','followers, for example their well-being.'],`<b>Very few.</b> Studies found a positive effect of green leadership on follower well-being (Iqbal &amp; Piwowar-Sulej, 2022) and a negative effect on turnover intentions (Li and colleagues, 2021). None examined the second part (7b): that leaders change how strongly followers' own green behavior pays off for them, for example by supporting and rewarding high levels or penalizing low levels. The path the authors name: "influencing others" and "taking initiative" build individual and shared perceptions that sustainability matters ("climate control and identity management").`),
rd('c',7,'🏭',['PROPOSITION 8 · A leader’s green behavior improves the','organization’s environmental performance.'],`<b>Several.</b> Studies found direct effects of green leadership on firms' environmental performance (Boiral and colleagues, 2015; Jang and colleagues, 2017; Riva and colleagues, 2021). The proposition: leader green behavior contributes directly, indirectly through leader and follower consequences, and (8b) by changing how strongly contextual antecedents affect organizational results. This bottom-up effect on a higher level is called <b>emergence</b>. Outcomes named: environmental performance and organizational attractiveness.`),
rd('d',1,'⬆️',['PROPOSITION 2 · Followers change their','leader’s green behavior (bottom-up).'],`<b>One study</b> (Javaid and colleagues, 2023), which is only somewhat consistent with the proposition and did not test the mechanisms.`),
rd('e',3,'⬇️',['PROPOSITION 4 · A leader’s green leadership goes','with followers’ green behavior.'],`<b>Several: this is the best-studied link of all.</b> 143 studies looked at follower green behavior as a consequence, and a meta-analysis found positive, moderate associations with green transformational leadership, servant leadership and supervisory support (Katz and colleagues, 2022). Keep in mind what was measured in most of them: a leadership <b>style</b> as seen by employees, not the leader's own green behavior.`),
rd('f',0,'🔗',['PROPOSITION 1 · A leader’s values and personality work','THROUGH knowledge, skills and motivation.'],`<b>None yet for the chain.</b> Several studies link leader antecedents to green leadership or leader green behavior. But the proposed mediation (indirect antecedents → direct antecedents → behavior) has so far not been empirically tested.`)];
SEQ('ldEvid','leOut',{title:'How much evidence is there for each proposition?',hook:'A conceptual model proposes; the dots show how much has been studied',unit:'Proposition',
 draw(S){let s='';ROWS.forEach((r,j)=>{const y=60+j*25,on=S['r'+j]||S.end,c=['#c0392b','#a8854a','#2f8a57'][r[2]];
   s+=`<circle cx="24" cy="${y+8}" r="10" fill="${on?'#c9a96e':'#fff'}" stroke="${on?'#a8854a':'#c9cfd9'}" stroke-width="1.8"/><text x="24" y="${y+12}" ${mid} font-size="11" font-weight="700" fill="${on?'#fff':'#9aa3b2'}">${r[0]}</text><text x="44" y="${y+12}" font-size="11.5" fill="#2b2f3a">${r[1]}</text>`+(on?[0,1,2].map(d=>`<circle cx="${400+d*22}" cy="${y+8}" r="7" fill="${(r[2]===2)||(r[2]===1&&d===0)?c:'#fff'}" stroke="${c}" stroke-width="1.8"/>`).join('')+`<text x="474" y="${y+12}" font-size="11" font-weight="700" fill="${c}">${['not tested','one or very few','several studies'][r[2]]}</text>`:`<text x="400" y="${y+12}" font-size="11" fill="#c9cfd9">?</text>`)});return s},
 rounds:shuf(RS),
 end:['Well studied: leader → followers’ behavior, context, organization results.','Hardly studied: followers’ influence on the leader, and results for leader and followers.'],
 endOut:`<b>🏁 Where the model is solid and where it is new.</b> In Figure 1 the authors draw <b>solid</b> arrows for more-established propositions and <b>dashed</b> arrows for less-established ones. The dots here follow what the text says about each proposition. For propositions 3 and 5, which you did not play: several studies link context to green leadership (3a, 3b), but only one cross-sectional study fits the interaction (3c); and several studies fit both parts of proposition 5.`});
})();

/* ---------- step 7 · doing better research ---------- */
(function(){
const M=[['o','⚡','Meters and bills','an outcome'],['s','📝','Questionnaires','a perception'],['v','🎥','Video observation','the behavior, at a price']];
const RS=[
{k:'a',m:'o',ic:'⚡',c:['The team’s energy use fell by twelve percent.','What does this number measure?'],q:'Choose.',o:[['An outcome of behavior,','not the behavior'],['The leader’s','green behavior']],say:`<b>An outcome.</b> Objective measures such as energy savings, resource consumption and waste production do not represent work performance, but the results of it. They may not be fully under a person's control, so they are better indicators of environmental <b>consequences</b> than of green behavior.`},
{k:'b',m:'s',ic:'📝',c:['Followers rate on a questionnaire','how green their leader acts.'],q:'What does this measure?',o:[['A perception of','the behavior'],['The actual','behavior']],say:`<b>A perception.</b> Common survey scales measure leaders' and followers' perceptions of their own or others' behavior. They can be biased by memory distortions and self-enhancement (the wish to look good).`},
{k:'c',m:'v',ic:'🎥',c:['Trained raters code video recordings','of the leader at work.'],q:'What is the price of this more accurate method?',o:[['It is costly, and people','act differently when watched'],['It can only capture','outcomes']],say:`<b>Cost and demand effects.</b> Observation with video may give a more accurate picture of green behavior, but takes more resources (recording, coding by trained raters) and may produce demand effects, because people know they are being observed. The advice: decide carefully what you intend to measure, and know the limits of each approach.`},
{k:'d',ic:'⏱️',c:['A one-moment survey reports: green leadership →','green climate → follower green behavior.'],q:'Can this design show the chain?',o:[['No: it needs several time','points or an experiment'],['Yes: the statistics','give the order']],say:`<b>No.</b> Cross-sectional designs are not suitable for propositions that involve causality, such as mediation models, or change within persons over time. Antecedents, behaviors and consequences should be measured at several time points, including a baseline, in longer longitudinal studies and shorter daily or weekly diary studies. For conclusive causal inferences, antecedents and behaviors need to be manipulated in experiments, for example training interventions. And use several sources (leader ratings, follower ratings, observation, objective outcomes) to avoid relationships that are inflated by common method bias.`},
{k:'e',ic:'🏷️',c:['What do the authors advise about new style labels','such as "green transformational leadership"?'],q:'Choose.',o:[['Stop making and','using them for now'],['Develop more','of them']],say:`<b>A moratorium</b> (a pause) on the continued development and use of "adjective leadership" styles, to avoid mixing up leader green behavior with its assumed antecedents (for example environmental motivation) or consequences (for example follower green behavior). Instead: define leader green behavior as concrete actions, with the green six.`},
{k:'f',ic:'➕',c:['Is a green leader simply a good, inspiring leader','in general? How would you find out?'],q:'Choose the design.',o:[['Measure both, and test what','green behavior adds'],['Measure only','green behavior']],say:`<b>Test what it adds.</b> Studies should show the influence of leader green behavior <b>incremental to</b> (on top of) established leadership constructs such as leader-member exchange, inspirational motivation and individualized consideration, and map its nomological network (how it relates to neighbouring constructs). So those constructs have to be measured too.`}];
SEQ('ldMeth','lmOut',{title:'How should leader green behavior be studied?',hook:'First: what does each instrument actually measure?',unit:'Question',
 draw(S){let s='';M.forEach((m,j)=>{const x=12+j*208,on=S.end||RS.some(r=>r.m===m[0]&&S.got[r.k]);s+=BX(x,62,200,120,on?'#e3ecf7':'#fff',on?'#34466b':'#c9cfd9',on?2.3:1.5)+`<text x="${x+100}" y="108" ${mid} font-size="30">${m[1]}</text><text x="${x+100}" y="136" ${mid} font-weight="700" font-size="12.5" fill="#34466b">${m[2]}</text><text x="${x+100}" y="156" ${mid} font-size="11.5" font-weight="700" fill="${on?'#a8854a':'#c9cfd9'}">${on?'measures '+m[3]:'measures ?'}</text>`});
  s+=BX(12,196,616,54,'#fbfaf6','#e3e0d8',1.4,14)+`<text x="320" y="219" ${mid} font-weight="700" font-size="12" fill="#6b7280">THE ADVICE</text><text x="320" y="238" ${mid} class="t-t" font-size="12">several sources · several time points · experiments · several levels</text>`;return s},
 rounds:RS,
 end:['No single instrument measures leader green behavior cleanly.','Combine sources, measure over time, and test causes with experiments.'],
 endOut:`<b>🏁 Five methodological recommendations.</b> (1) Think about what each measure captures. (2) Use several sources and several time points; experiments for causality. (3) Sample leaders and followers at different hierarchical levels, from chief executive officers to first-line supervisors, to study "trickle-down" effects (top → middle management → employees and possibly customers) and "bottom-up" effects (employees → leaders → the organization). (4) Test what leader green behavior adds beyond established leadership constructs. (5) Compare the relative importance of predictors at different levels, and their interactions, in one study; archival data on organizational initiatives (for example buying carbon offsets) can help.`});
})();

Object.assign(TT,{
'r-lead-1':{fit:'Reading 1 placed leadership at the team level as one of many causes of employee green behavior. This reading puts the leader in the middle and asks a prior question: what exactly is a green leader doing?',
 key:'Earlier research studied <b>styles</b> with an adjective in front. A style label mixes three things: what the leader is or wants, what the leader does, and what results. The authors want to study the <b>behavior</b> itself.',
 think:'A restaurant review that says "an inspiring chef". Does that describe the chef\'s training, what the chef does in the kitchen, or how the food tastes? Until you separate those, you cannot find out what makes the food good.',
 friend:'"Research on green leadership mostly used labels like green transformational leadership. Such a label already assumes good motives and good results. These authors say: look at what leaders actually do, and keep causes and results apart."',
 hook:'<b>Before · the behavior · after.</b> Never three in one word.',
 tip:'If a question asks what the authors criticize about earlier research, there are two answers: (1) adjective leadership styles conflate behavior with antecedents or consequences; (2) the literature is fragmented.'},
'r-lead-2':{fit:'Before building a model, the authors show what research has and has not done. The gaps you find here are exactly the places where their model adds new arrows.',
 key:'Of 210 papers, most studied a <b>style</b> (above all green transformational leadership) and its link with <b>followers\' green behavior</b>. Very few studied what <b>leads to</b> green leadership, and almost none studied followers as a cause or outcomes for leaders.',
 think:'A city map where one neighbourhood is drawn street by street and the rest is blank. The drawn part is "leader style → follower behavior". The model in the next steps sketches the blank parts.',
 friend:'"They found 210 papers. Most show that a green leadership style goes with greener employees. Hardly any ask where a leader\'s green behavior comes from, or what it does for the leader."',
 hook:'<b>62 · 143 · 28 · 1.</b> Most-used label, most-studied outcome, studies on antecedents, studies on followers as a cause.',
 tip:'Table 1 is a likely source of questions. Know the order of magnitude: consequences (191) far more than antecedents (28); follower green behavior (143) far more than organizational environmental results (33).'},
'r-lead-3':{fit:'To answer what the role of leadership is in promoting green behavior, you first need the two definitions on which the rest of the article stands.',
 key:'<b>Leadership</b> here is a <b>process</b> of directing, controlling or influencing followers and the organization toward sustainability goals. <b>Leader green behavior</b> is the leader\'s own countable actions, which help or harm the environment <b>directly</b> or <b>indirectly</b> through context, followers or the organization.',
 think:'A gardener. She can water a plant herself (direct), install a sprinkler system (context), teach the neighbours to water (followers), or convince the town to plant a park (organization). All four are her gardening.',
 friend:'"Leader green behavior is everything a leader does that helps or harms the environment: her own recycling or flying, but also the policies she makes, how she steers her people, and what she pushes for in company decisions."',
 hook:'<b>Herself · the context · her people · the organization.</b>',
 tip:'Two details that are easy to miss: leader green behavior includes <b>harmful</b> behavior, and it can be shown by people <b>without a formal leadership role</b> (shared or emergent leadership).'},
'r-lead-4':{fit:'Reading 1 asked what leads to employee green behavior. The same question is now asked about the leader, with one new idea: followers can change their leader.',
 key:'Three ways in: the leader\'s <b>own antecedents</b> (1), the <b>followers</b> from below (2), and the <b>context</b> from above (3). The context can also make the leader\'s own motivation matter more or less.',
 think:'A thermostat and an open window. A strict policy is a thermostat: it sets the temperature whatever you prefer (strong situation). A green office is an open window on a warm day: it does not force you, but if you like fresh air you will now act on it (trait activation).',
 friend:'"A leader acts green because of who she is and what she knows, because her team nudges or shows her, and because the organization makes it possible. And a strict rule makes her own motivation matter less."',
 hook:'<b>From within (1) · from below (2) · from above (3).</b>',
 tip:'Situation strength and trait activation are both about <b>interaction</b> (proposition 3c): the context changes how strongly a personal characteristic shows in behavior. Strong situation: weaker link. Trait-activating context: stronger link.'},
'r-lead-5':{fit:'This is the core of the learning question on the role of leadership: by which routes does what a leader does end up in what employees do?',
 key:'Four named routes: <b>person-focused action</b> and <b>behavioral modeling</b> go straight to followers; <b>system-focused action</b> and <b>moderating action</b> go through the context. On top of that, the leader changes how strongly followers\' own antecedents work.',
 think:'A sports coach. She can train the players (person-focused), play the move herself so they see it (modeling), change the training schedule and the pitch (system-focused), or decide how strictly the club\'s new rule is applied in her team (moderating).',
 friend:'"A leader makes her team greener in four ways: she teaches and encourages them, she sets the example, she changes the rules and the work, and she decides how much of the company\'s green policy really lands in her team."',
 hook:'<b>Teach them · show them · change the system · steer the system.</b>',
 tip:'System-focused action <b>changes</b> a contextual factor. Moderating action leaves the factor as it is and changes its <b>effect</b> on followers. If the case says "decides whether and how to implement", it is moderating action.'},
'r-lead-6':{fit:'A model is only as useful as its support. This step shows which parts rest on many studies and which are new ideas, so that you can say how sure we are about the role of leadership.',
 key:'Leader green behavior is proposed to bring results for the <b>leader</b> (6), the <b>followers</b> (7) and the <b>organization</b> (8). Only the organization-level results and the link with followers\' green behavior are well studied.',
 think:'A weather map with measured temperatures in some cities and forecasts in others. Propositions 4, 5 and 8 are measured. Propositions 1, 2, 6 and 7 are mostly forecast.',
 friend:'"We know quite well that green leadership goes with greener employees and better environmental results for the company. We know almost nothing about what it does for the leaders themselves, or whether employees can make their boss greener."',
 hook:'<b>Solid arrows = studied. Dashed arrows = proposed.</b>',
 tip:'This is a <b>conceptual paper</b>: the eight propositions are proposals, not findings. In an answer, write "the model proposes" and add how much evidence the text reports.'},
'r-lead-7':{fit:'The article ends with advice for future research. It tells you how to judge any study on green leadership you meet in this theme, including readings 5 and 6.',
 key:'Measure <b>behavior</b>, not outcomes or impressions alone; use <b>several sources and time points</b>; test causes with <b>experiments</b>; study <b>several levels</b>; and stop inventing new style labels.',
 think:'Judging a driver. The fuel bill is an outcome (it also depends on the car and the traffic). Asking passengers gives an impression. A dashboard camera shows the driving itself, but the driver knows it is there.',
 friend:'"To really study green leaders you cannot just hand out one questionnaire. An energy bill is not behavior, a survey is an opinion about behavior, and video is expensive. So combine them and follow people over time."',
 hook:'<b>Meter = outcome · survey = perception · video = behavior, at a price.</b>',
 tip:'The same critique applies to most studies in this theme: one-moment surveys cannot test a mediation chain. If a question gives such a design and a causal conclusion, that is the weak spot.'},
'r-lead-8':{fit:'The article in one view, and what it adds to reading 1 for the question of what leaders can do to make employees engage in green behavior.',
 key:'Two contributions: <b>clear definitions</b> (leadership as a process; leader green behavior as concrete actions in six dimensions) and <b>one model</b> with eight propositions that links antecedents and consequences at the levels of the organization, the leader and the followers.',
 think:'Reading 1 was a wide-angle photo of the whole landscape. This reading zooms in on one figure in it, the leader, and draws every line that runs to and from that figure.',
 friend:'"Leaders matter for sustainability in more ways than inspiring people. They act themselves, set the example, teach, change the system and decide how company policy lands. And they are shaped in turn by their own knowledge and motivation, by their team and by their organization."',
 hook:'<b>Define the behavior · three ways in · five ways out · three kinds of results.</b>',
 tip:'For "what is the role of leadership in promoting employee green behavior", build the answer from propositions 4 and 5 (four named pathways plus the interaction) and add the evidence level from the meta-analysis.'}
});

Object.assign(GLOSS,{
lgb:['Leader green behavior','What a leader does, countable or ratable and under the leader\'s control, that helps or harms environmental sustainability, directly or through the context, followers or the organization.'],
adjlead:['"Adjective leadership" styles','Leadership styles named with an adjective (transformational, servant, ethical). The label describes a pattern of behavior together with its assumed causes or good results.'],
conflate:['Conflate','To mix two different things up and treat them as one.'],
sitstr:['Situation strength','How much a situation limits people\'s free choice. In a strong situation, personal differences show less in behavior.'],
traitact:['Trait activation','The idea that a context which is relevant to a personal characteristic brings that characteristic out in behavior.'],
emerg:['Emergence','Effects from a lower level adding up to an outcome at a higher level, for example individual behavior adding up to an organization\'s result.'],
shared:['Shared or emergent leadership','Leadership shown by people without an official leadership role.'],
trickle:['Trickle-down effect','Behavior passing down the hierarchy, from top management through middle managers to employees.'],
mediator:['Mediator','The link in the middle: A affects B through the mediator.'],
moderator:['Moderator','Something that changes how strong a link between two other things is.'],
envgoals:['Environmental sustainability goals','Targets or standards, for a person, a group or an organization, for dealing responsibly with nature. Examples: zero emissions, zero waste to landfill, responsible consumption.']
});
